INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6c5-7f54-b639-d7a7557042e9'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Write an expression in terms of n for the nth term of the sequence 78, 69, 60, 51, ...', '87 - 9n', 'The first term is 78 and the common difference is -9. So the nth term is 78 + (n - 1)(-9) = 87 - 9n.', 'Easy', '{"tags":"algebra,sequences,nth-term","subtopic":"nth term","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.861Z'::timestamptz, '2026-07-26T12:42:25.861Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6ca-7903-9322-9edf29f8572c'::uuid, '019f9df7-a2a2-7888-aef2-fd58477eb864'::uuid, 'The universal set contains the integers from 1 to 15. Set A contains the perfect squares and set B contains the prime numbers. Find n(A ∪ B).', '9', 'A = {1, 4, 9}. B = {2, 3, 5, 7, 11, 13}. There is no overlap, so n(A ∪ B) = 3 + 6 = 9.', 'Easy', '{"tags":"sets,union,number-of-elements","subtopic":"set operations","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.866Z'::timestamptz, '2026-07-26T12:42:25.866Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6cd-76b7-8761-7b183729226c'::uuid, '019f9df7-a2a2-7888-aef2-fd58477eb864'::uuid, 'The universal set contains the integers from 1 to 15. Set B contains the prime numbers. List the elements of B''.', '{1, 4, 6, 8, 9, 10, 12, 14, 15}', 'The primes from 1 to 15 are 2, 3, 5, 7, 11 and 13. The complement B'' contains all other integers in the universal set.', 'Easy', '{"tags":"sets,complement,prime-numbers","subtopic":"complement of a set","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.869Z'::timestamptz, '2026-07-26T12:42:25.869Z'::timestamptz) ON CONFLICT (id) DO NOTHING;